class Solution {
public:
    int smallestBalancedIndex(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        vector<long long> suffix(n + 1, 1);
        for (int i = n - 1; i >= 0; --i) {
            if (suffix[i + 1] > total / nums[i]) suffix[i] = total + 1;
            else suffix[i] = suffix[i + 1] * nums[i];
        }
        long long leftSum = 0;
        for (int i = 0; i < n; ++i) {
            if (leftSum == suffix[i + 1]) return i;
            leftSum += nums[i];
        }
        return -1;
    }
};
